Translate("frFR", "blasted-lands", {
	title = "Terres foudroyées",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Terres foudroyées s'étendent à l'extrémité sud des {link:eastern-kingdoms}Royaumes de l'est{/link}, au-dessous du {link:swamp-of-sorrows}Marais des Chagrins{/link}. Rien de vert n'y pousse. La terre est rouge comme une plaie et les collines sont nues. Le ciel vacille d'éclairs qui n'apportent aucune pluie. À l'extrémité sud de ce désert se dresse la {link:dark-portal}Porte des Ténèbres{/link}, la porte par laquelle la {link:horde}Horde{/link} orque entra pour la première fois dans le monde. La porte est aujourd'hui sombre et silencieuse. Pourtant, la terre qui l'entoure n'a jamais guéri. {link:ogres}Ogres{/link}, démons et cultistes en ont fait leur domaine, et une seule forteresse de l'{link:alliance}Alliance{/link} veille sur la route.]=],
		},
		{
			title = "Origines",
			text = [=[Avant la venue des orcs, ce pays formait la partie sud du Noir Marécage, un sombre marais qui s'étendait au sud des marécages. C'est là que le démoniste {link:gul-dan}Gul'dan{/link} et le Gardien {link:medivh}Medivh{/link} ouvrirent leur porte entre les mondes, et que la {link:horde}Horde{/link} sortit du bourbier pour s'abattre sur le royaume de {link:kingdom-of-stormwind}Stormwind{/link}. La magie gangrenée qui avait dressé la Porte empoisonna le marais alentour. Quand l'{link:alliance}Alliance{/link} brisa la porte à la fin de la {link:second-war}Deuxième Guerre{/link}, la terre subit une seconde blessure. L'eau mourut, les roseaux se flétrirent et le sol brûla jusqu'à prendre la couleur qu'il porte aujourd'hui. Les gens des royaumes donnèrent à ce pays ruiné un nom simple et amer, et il l'a gardé depuis.]=],
		},
		{
			title = "De nos jours",
			text = [=[La Porte est silencieuse depuis bien des années, mais les Terres foudroyées ne se sont pas tues avec elle. Après que la {link:burning-legion}Légion ardente{/link} eut été brisée lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, un reste de son armée se retira dans la {link:the-tainted-scar}Balafre impure{/link}, au sud-ouest, sous le seigneur funeste {link:lord-kazzak}Kazzak{/link}. Son lieutenant, le démon {link:razelikh-the-defiler}Razelikh le Souilleur{/link}, a passé les années qui ont suivi à lier à lui les autres puissances du pays. Les cultistes des Shadowsworn le servent. Les ogres Cognepeur aussi, dont le chef est désormais plus démon qu'{link:ogres}ogre{/link}. Quelques draeneï perdus errent dans les étendues désolées, cherchant un chemin pour rentrer chez eux. À la lisière nord de tout cela se dresse {link:nethergarde-keep}Rempart-du-Néant{/link}, où les mages du {link:kirin-tor}Kirin Tor{/link} et les soldats qui les gardent étudient la Porte et attendent le jour où elle s'éveillera. La route vers la forteresse est longue, et les caravanes qui la nourrissent n'arrivent pas toujours.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les veilleurs de {link:nethergarde-keep}Rempart-du-Néant{/link}.{/b} Mages, clercs, soldats et mineurs tiennent la forteresse et ses mines dans les collines du nord. Ils sont peu nombreux, et loin de chez eux.
• {b}Les ogres Cognepeur.{/b} Les Cognepeur tiennent le nord-ouest des terres désolées et parcourent leur centre. Leurs démonistes et leurs mages ogres ont appris des arts obscurs auprès de leur maître démoniaque.
• {b}Les Shadowsworn.{/b} Ces cultistes tiennent les grottes des {link:serpent-s-coil}Anneaux du serpent{/link} et l'Autel des tempêtes, à l'ouest. Ils sont les héritiers de l'ancien {link:shadow-council}Conseil des ombres{/link}, et ils servent {link:razelikh-the-defiler}le Souilleur{/link}.
• {b}La {link:burning-legion}Légion ardente{/link}.{/b} Gardes funestes, seigneurs de l'effroi, gangregardes et gangrechiens hantent la {link:the-tainted-scar}Balafre impure{/link} et les abords de la {link:dark-portal}Porte des Ténèbres{/link}.
• {b}Les draeneï perdus.{/b} Des exilés misérables d'un peuple ancien errent sur cette terre. Certains sont fous, et certains espèrent encore.
• {b}Les bêtes des terres désolées.{/b} Hyènes, basilics, scorpides, vautours et grands sangliers sont devenus forts et étranges dans la terre souillée.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}Le Noir Marécage.{/b} Aucune chronique ne dit combien de temps le marais resta en paix avant la venue des orcs. Il était reculé, humide et presque vide d'habitants.
• {b}La Première Guerre.{/b} La {link:dark-portal}Porte des Ténèbres{/link} s'ouvrit dans le marais, et la {link:horde}Horde{/link} y bâtit ses premières places fortes. Depuis le Marécage, elle marcha vers le nord et l'ouest pour commencer la {link:first-war}Première Guerre{/link}.
• {b}La {link:second-war}Deuxième Guerre{/link}.{/b} Quand l'{link:alliance}Alliance de Lordaeron{/link} eut vaincu la Horde, ses soldats descendirent vers le sud et détruisirent la Porte. La terre autour de la porte fut brûlée et tordue par cette destruction.
• {b}{link:nethergarde-keep}Rempart-du-Néant{/link}.{/b} À l'instigation de l'archimage {link:khadgar}Khadgar{/link}, le {link:kirin-tor}Kirin Tor{/link} éleva Rempart-du-Néant sur la seule route menant aux terres désolées. Les rois de l'Alliance payèrent ses murs.
• {b}La Porte rouverte.{/b} Quelques années plus tard, la porte s'embrasa de nouveau. Des orcs arrivèrent de {red:draenor}Draenor{/red} et assiégèrent Rempart-du-Néant. L'Alliance envoya une armée à leur poursuite à travers la Porte, et la porte fut détruite une seconde fois. L'expédition ne revint pas.
• {b}De nos jours.{/b} Depuis, la Porte est restée froide. Le reste de la Légion vint dans la {link:the-tainted-scar}Balafre impure{/link} après la {link:third-war}Troisième Guerre{/link}, et un régiment de la Horde qui marcha dans les terres désolées pour les reconnaître fut perdu presque jusqu'au dernier homme.]=],
		},
		{
			title = "Récits des terres désolées",
			text = [=[• On dit qu'aucune pluie n'a jamais atteint le sol des Terres foudroyées. Les orages qui éclatent sur les collines de l'est s'écoulent vers la mer avant que l'argile rouge puisse boire.
• Les bêtes des terres désolées ne ressemblent pas à leurs semblables d'ailleurs. Deux mages de sang elfes, à la frontière nord, soutiennent que les énergies libérées par la Porte les ont forcées à changer, et ils paient bien pour en avoir la preuve.
• Les voyageurs qui atteignent la frontière sud du marais rencontrent parfois le fantôme d'un {link:orcs}orc{/link} qui se tient au bord de la route. Il les avertit de faire demi-tour. Il sait ce qui attend au-delà.
• On dit qu'un grand drake noir nommé Teremus the Devourer tourne autour de la {link:dark-portal}Porte des Ténèbres{/link}. Les veilleurs de {link:nethergarde-keep}Rempart-du-Néant{/link} comptent les patrouilles qu'il a emportées.
• Au fond de la {link:the-tainted-scar}Balafre impure{/link}, loin de toute route, un vieux démoniste humain nommé {link:daio-the-decrepit}Daio{/link} entretient un autel parmi les démons. Il n'est pas leur prisonnier.]=],
		},
	},
})

Translate("frFR", "nethergarde-keep", {
	title = "Rempart-du-Néant",
	aliases = { "Rempart", "forteresse de Rempart-du-Néant" },
	sections = {
		{
			title = "Résumé",
			text = [=[Rempart-du-Néant se dresse sur un haut escarpement au nord-est des {link:blasted-lands}Terres foudroyées{/link}, au-dessus de la seule route menant aux terres désolées. Le {link:kirin-tor}Kirin Tor{/link} l'éleva après la {link:second-war}Deuxième Guerre{/link} pour surveiller la {link:dark-portal}Porte des Ténèbres{/link} brisée, et les rois de l'{link:alliance}Alliance{/link} payèrent ses pierres. Son fondateur, l'archimage {link:khadgar}Khadgar{/link}, franchit la Porte il y a longtemps et ne revint pas. La forteresse a poursuivi sa veille sans lui.]=],
		},
		{
			title = "En ces jours",
			text = [=[Rempart-du-Néant est un lieu austère et affairé. Ses analystes et ses guetteurs de faille étudient la Porte depuis la tour des mages. Ses clercs soignent les blessés et ses soldats tiennent les murs contre les raids des Cognepeur. Ses mineurs creusent dans les collines derrière elle. Tout le reste doit venir par la longue route de {link:stormwind-city}Stormwind{/link}, à travers {link:darkshire}Darkshire{/link} et le marais. Des caravanes se perdent en chemin, victimes des ogres et des bêtes, et l'intendant compte chaque caisse qui lui parvient. La forteresse est aussi un lieu de rencontres. Un devin Wildhammer travaille dans sa tour, et un envoyé elfe soutient dans sa grande salle que l'{link:alliance}Alliance{/link} combat le mauvais ennemi.]=],
		},
	},
})

Translate("frFR", "garrison-armory", {
	title = "Armurerie de la garnison",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Armurerie de la garnison se trouve dans les collines derrière {link:nethergarde-keep}Rempart-du-Néant{/link}, là où la garnison du {link:kirin-tor}Kirin Tor{/link} a ouvert des mines dans la roche rouge. Les mineurs de Rempart-du-Néant travaillent dans ses galeries sous l'œil des contremaîtres et des ingénieurs. Le minerai qu'ils remontent est l'une des rares choses que les {link:blasted-lands}Terres foudroyées{/link} donnent librement. Il forge les armes de la forteresse et paie une partie des marchandises qui doivent venir du nord par la route. C'est un dur labeur en un lieu dur, et les mineurs savent que les soldats sur les murs au-dessus d'eux sont tout ce qui se dresse entre les puits et les ogres des terres désolées.]=],
		},
	},
})

Translate("frFR", "dreadmaul-hold", {
	title = "Bastion Cognepeur",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Bastion Cognepeur est la place forte des ogres Cognepeur, au nord-ouest des {link:blasted-lands}Terres foudroyées{/link}, près du col qui descend du marais. Ses brutes et ses mages ogres attaquent la route de {link:nethergarde-keep}Rempart-du-Néant{/link}, et ils ont rendu les terres désolées du nord dangereuses pour toute caravane. Leur maître est {link:grol-the-destroyer}Grol le Destructeur{/link}. Il fut jadis un chef {link:ogres}ogre{/link} comme un autre, mais il se vendit au démon {link:razelikh-the-defiler}Razelikh{/link} contre l'immortalité, et il n'est plus un ogre. Dans le bastion, trois soldats asservis d'un régiment perdu de la {link:horde}Horde{/link} sont liés à son service. Ils ne peuvent mourir, et ils ne peuvent partir.]=],
		},
	},
})

Translate("frFR", "dreadmaul-post", {
	title = "Poste Cognepeur",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Poste Cognepeur est un camp d'ogres au cœur des {link:blasted-lands}Terres foudroyées{/link}, au sud de la {link:rise-of-the-defiler}Cime du Souilleur{/link}. Les Cognepeur qui le tiennent sont les plus dangereux de leur tribu : de grands écraseurs et des démonistes ogres qui ont appris à invoquer la puissance gangrenée. Ils gardent le milieu des terres désolées et le chemin de la {link:dark-portal}Porte des Ténèbres{/link}. Les Cognepeur vinrent sur ces terres dans le sillage des orcs, et ils ne repartirent jamais. Leurs mages ogres et leurs démonistes prouvent que les démons de la {link:the-tainted-scar}Balafre impure{/link} ont trouvé en eux des élèves bien disposés.]=],
		},
	},
})

Translate("frFR", "serpent-s-coil", {
	title = "Anneaux du serpent",
	sections = {
		{
			title = "Résumé",
			text = [=[Les Anneaux du serpent sont un dédale sinueux de grottes à l'est des {link:blasted-lands}Terres foudroyées{/link}. Des carcasses calcinées de bâtiments orcs, vestiges des guerres, se dressent devant leurs entrées. Les cultistes des Shadowsworn en ont fait leur repaire, et l'archimage {link:archmage-allistarj}Allistarj{/link} les commande de l'intérieur. C'est ici que les soldats d'un régiment perdu de la {link:horde}Horde{/link} furent torturés, et ici que leur lieutenant, {link:kirith-the-damned}Kirith{/link}, fut brisé. Dans la grotte la plus profonde rôde désormais une monstrueuse bête gangrenée. Ce fut jadis un homme, et elle porte encore un nom.]=],
		},
	},
})

Translate("frFR", "rise-of-the-defiler", {
	title = "Cime du Souilleur",
	sections = {
		{
			title = "Résumé",
			text = [=[La Cime du Souilleur est la plus haute montagne des {link:blasted-lands}Terres foudroyées{/link}, un pic de pierre rouge près du milieu des terres désolées. Son sommet est l'antre de {link:razelikh-the-defiler}Razelikh le Souilleur{/link}, le seigneur démon du pays. Aucun sentier ne mène au sommet. Des runes gravées au pied de la montagne peuvent y transporter, mais seulement celui qui détient l'amulette du Souilleur lui-même. Au pied de la cime attend un spectre, le {link:deathly-usher}Deathly Usher{/link}, lié à ce monde pour toujours. Au sommet se dresse l'Autel du Souilleur, où le démon peut être appelé.]=],
		},
	},
})

Translate("frFR", "the-tainted-scar", {
	title = "La Balafre impure",
	aliases = { "Balafre impure" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Balafre impure est une large entaille de terre morte au sud-ouest des {link:blasted-lands}Terres foudroyées{/link}. Elle faisait jadis partie du Noir Marécage. C'est aujourd'hui le dernier bastion de la {link:burning-legion}Légion ardente{/link} sur ces terres. Après la défaite du {link:battle-of-mount-hyjal}mont Hyjal{/link}, le seigneur funeste {link:lord-kazzak}Kazzak{/link} se retira ici avec ce qui restait de son armée, et il y est resté. Commandants gardes funestes, seigneurs de l'effroi, gangregardes et chiens de mana emplissent la Balafre. Aucune armée des royaumes n'a tenté de la reprendre.]=],
		},
		{
			title = "L'autel du démoniste",
			text = [=[À la lisière nord de la Balafre se dresse un autel où un vieux démoniste humain, {link:daio-the-decrepit}Daio le Décrépit{/link}, a élu domicile parmi les démons. Ceux qui le cherchent viennent apprendre comment lier un démon de la garde funeste.]=],
		},
	},
})

Translate("frFR", "lord-kazzak", {
	title = "Seigneur Kazzak",
	subtitle = "Commandant du reste de la Légion",
	found = "La Balafre impure, au sud-ouest des Terres foudroyées",
	hint = [=[Cherchez le seigneur démon qui commande la Balafre impure. N'y allez pas seul.]=],
	allegiance = "Légion ardente",
	aliases = { "Kazzak" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le seigneur Kazzak est un seigneur funeste de la {link:burning-legion}Légion ardente{/link}, un démon colossal qui commande ce qui reste de l'armée de la Légion dans les {link:eastern-kingdoms}Royaumes de l'est{/link}. Il tient la {link:the-tainted-scar}Balafre impure{/link}, au sud-ouest des {link:blasted-lands}Terres foudroyées{/link}. Gardes funestes, seigneurs de l'effroi et gangregardes l'y servent.]=],
		},
		{
			title = "Importance",
			text = [=[Quand {link:archimonde}Archimonde{/link} tomba au {link:battle-of-mount-hyjal}mont Hyjal{/link}, les armées de la Légion sur {link:azeroth}Azeroth{/link} furent brisées. L'armée de Kazzak ne périt pas. Elle se replia dans la {link:the-tainted-scar}Balafre impure{/link}, près de la {link:dark-portal}Porte des Ténèbres{/link} silencieuse, et elle y est restée. De tous les démons restés dans le monde, peu sont aussi puissants. Depuis la Balafre, il chargea son plus féroce lieutenant, {link:razelikh-the-defiler}Razelikh le Souilleur{/link}, de soumettre le reste des terres désolées à l'ombre de la Légion. Les veilleurs de {link:nethergarde-keep}Rempart-du-Néant{/link} croient que les ogres Cognepeur le servent aussi.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il mena le reste de la Légion dans la {link:the-tainted-scar}Balafre impure{/link} après la défaite du mont Hyjal.
• Il chargea {link:razelikh-the-defiler}Razelikh le Souilleur{/link} de s'assurer des {link:blasted-lands}Terres foudroyées{/link}.
• Il tient encore la Balafre avec une armée de gardes funestes, de seigneurs de l'effroi et de gangregardes.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune chronique des royaumes ne rapporte quand Kazzak vint pour la première fois sur {link:azeroth}Azeroth{/link}, ni ce qu'il cherche en s'attardant si près de la {link:dark-portal}Porte des Ténèbres{/link}. Les mages de {link:nethergarde-keep}Rempart-du-Néant{/link} ont leurs craintes, mais ils ne les disent pas à voix haute.]=],
		},
	},
	chapters = {
		{
			title = "Le maître du Souilleur",
			hint = "Apprenez du chasseur de démons d'Azshara qui sert Razelikh.",
			text = [=[Le chasseur de démons {link:loramus-thalipedes}Loramus Thalipedes{/link} raconta l'histoire sans détour. Au temps de la guerre, {link:razelikh-the-defiler}Razelikh{/link} avait été le plus redouté des lieutenants de Kazzak. Quand la Légion fut battue et Kazzak repoussé dans la {link:the-tainted-scar}Balafre impure{/link}, c'est Razelikh qui fut envoyé tenir le pays pour lui. Chaque {link:ogres}ogre{/link} et chaque cultiste qui sert le Souilleur sert, au bout du compte, le seigneur funeste de la Balafre.]=],
		},
	},
	mentions = {
		{
			text = [=[{link:loramus-thalipedes}Loramus{/link}, l'histoire du Souilleur]=],
		},
	},
	bonds = {
		{ id = "razelikh-the-defiler", name = "Razelikh le Souilleur", note = "son lieutenant" },
		{ id = "archimonde", name = "Archimonde", note = "son commandant tombé" },
	},
})

Translate("frFR", "razelikh-the-defiler", {
	title = "Razelikh le Souilleur",
	subtitle = "Seigneur démon des Terres foudroyées",
	found = [=[Au sommet de la Cime du Souilleur, quand il est appelé par sa propre amulette]=],
	hint = [=[Seul celui qui détient l'amulette du Souilleur peut monter jusqu'à son antre.]=],
	allegiance = "Légion ardente",
	aliases = { "Razelikh", "le Souilleur", "Rakh'likh" },
	sections = {
		{
			title = "Résumé",
			text = [=[Razelikh le Souilleur est un seigneur de l'effroi de la {link:burning-legion}Légion ardente{/link} et le véritable maître des {link:blasted-lands}Terres foudroyées{/link}. Il fut jadis le plus redouté des lieutenants du seigneur {link:lord-kazzak}Kazzak{/link}. Il règne aujourd'hui sur les terres désolées depuis un antre au sommet de la plus haute montagne du pays, et les ogres et les cultistes de la région le servent.]=],
		},
		{
			title = "Importance",
			text = [=[Quand la Légion fut vaincue et que {link:lord-kazzak}Kazzak{/link} se retira dans la {link:the-tainted-scar}Balafre impure{/link}, Razelikh fut envoyé s'assurer du pays. Il le fit par la ruse plus que par la force. Tandis que l'{link:alliance}Alliance{/link} et la {link:horde}Horde{/link} se querellaient pour des terres loin au nord, il rassembla les sectes éparses du {link:shadow-council}Conseil des ombres{/link} et les ogres Cognepeur. Le prix qu'il offrait était le pouvoir. Il fit une amulette, la brisa en trois, et en donna un morceau à chacun : l'archimage {link:archmage-allistarj}Allistarj{/link}, dame {link:lady-sevine}Sevine{/link} et {link:grol-the-destroyer}Grol le Destructeur{/link}. Chaque morceau rendait son porteur immortel dans les {link:blasted-lands}Terres foudroyées{/link}. Chaque morceau liait aussi son porteur à le servir pour toujours. Ses trois capitaines ne comprirent le second don que lorsqu'il fut trop tard.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il s'assura des {link:blasted-lands}Terres foudroyées{/link} pour {link:lord-kazzak}Kazzak{/link} après la défaite de la Légion.
• Il unit sous son commandement les cultistes des Shadowsworn et les ogres Cognepeur.
• Il captura un régiment de la {link:horde}Horde{/link} et fit des âmes de ses soldats des esclaves immortels.
• Il lia trois capitaines à lui grâce aux morceaux de son amulette.]=],
		},
	},
	chapters = {
		{
			title = "Le régiment",
			hint = [=[Écoutez l'histoire du héros déchu de la Horde à la lisière du marais.]=],
			text = [=[Le fantôme de la frontière du marais était jadis Trebor, un commandant de la {link:horde}Horde{/link}. Il mena un régiment dans les terres désolées, et les serviteurs du Souilleur s'en emparèrent. Razelikh arracha les âmes des soldats capturés et lia leurs corps à des pierres. Il en garda neuf pour lui, liés près de la {link:dark-portal}Porte des Ténèbres{/link}. Les neuf autres, il les partagea entre ses capitaines, trois chacun. Privés de leur âme, ces hommes ne peuvent mourir. C'est leur capture, dit le chasseur de démons {link:loramus-thalipedes}Loramus{/link}, qui scella le pacte entre le démon, les cultistes et les ogres.]=],
		},
		{
			title = "Les pierres de lien",
			hint = "Libérez les soldats liés du régiment perdu.",
			text = [=[{link:kirith-the-damned}Kirith{/link} avait trouvé la faille avant d'être perdu. Chaque soldat lié pouvait être battu jusqu'au seuil de la dissolution, et en cet instant seulement, sa pierre de lien pouvait être brisée. Dix-huit pierres furent brisées à travers les {link:blasted-lands}Terres foudroyées{/link}, près de la Porte et dans les repaires des trois capitaines. Les soldats du régiment furent libérés et purent enfin reposer. Razelikh perdit ses gardes immortels, et il apprit que quelqu'un le traquait.]=],
		},
		{
			title = "L'amulette brisée",
			hint = "Brisez la triade et reconstituez l'amulette.",
			text = [=[Aucune lame ordinaire ne pouvait blesser les trois capitaines. Le chasseur de démons {link:loramus-thalipedes}Loramus Thalipedes{/link} connaissait le vrai nom du Souilleur, et avec le forgeron {link:galvan-the-ancient}Galvan l'Ancien{/link}, il aida à forger des armes d'azsharite qui le portaient. Avec ces armes, {link:grol-the-destroyer}Grol{/link}, {link:lady-sevine}Sevine{/link} et {link:archmage-allistarj}Allistarj{/link} furent abattus, et leurs trois morceaux de l'amulette furent de nouveau réunis. Le Souilleur sentit la rupture dans sa chaîne de commandement. Il sut qu'il était traqué.]=],
		},
		{
			title = "Vous êtes Rakh'likh",
			hint = "Utilisez l'amulette à l'Autel du Souilleur.",
			text = [=[L'amulette ouvrit le chemin du sommet. À l'Autel du Souilleur, le démon fut appelé. Il invoqua ses serviteurs, Ilifar le Gardien des âmes et Felcular son champion, et il combattit au bord de la montagne. Il tomba. L'une de ses cornes fut descendue de la montagne, preuve que le seigneur démoniaque des {link:blasted-lands}Terres foudroyées{/link} pouvait être vaincu. La protection qu'il avait forgée fut remise à Trebor pour être détruite, afin que nul ne puisse plus s'en servir.]=],
		},
	},
	mentions = {
		{
			text = [=[Querelles mesquines, la route de l'{link:alliance}Alliance{/link} vers le héros déchu]=],
		},
		{
			text = [=[La chute, la route de la {link:horde}Horde{/link} vers le héros déchu]=],
		},
		{ text = "Le couvert des ténèbres, le secret de la triade" },
		{ text = "Le chasseur de démons" },
		{ text = "Retour dans les {link:blasted-lands}Terres foudroyées{/link}" },
	},
	bonds = {
		{ id = "lord-kazzak", name = "Seigneur Kazzak", note = "son maître" },
		{ id = "grol-the-destroyer", name = "Grol le Destructeur", note = "capitaine lié" },
		{ id = "archmage-allistarj", name = "Archimage Allistarj", note = "capitaine lié" },
		{ id = "lady-sevine", name = "Dame Sevine", note = "capitaine liée" },
		{ id = "fallen-hero-of-the-horde", name = "Héros déchu de la Horde", note = "son captif et son ennemi" },
		{ id = "loramus-thalipedes", name = "Loramus Thalipedes", note = "connaît son vrai nom" },
	},
})

Translate("frFR", "grol-the-destroyer", {
	title = "Grol le Destructeur",
	subtitle = "Seigneur des Cognepeur",
	found = "Bastion Cognepeur, au nord-ouest des Terres foudroyées",
	hint = "Cherchez le seigneur des ogres dans leur bastion du nord.",
	allegiance = "Cognepeur · Razelikh le Souilleur",
	aliases = { "Grol" },
	sections = {
		{
			title = "Résumé",
			text = [=[Grol le Destructeur règne sur les ogres Cognepeur depuis le {link:dreadmaul-hold}Bastion Cognepeur{/link}. Il fut jadis un chef {link:ogres}ogre{/link}. Il prit un tiers de l'amulette de {link:razelikh-the-defiler}Razelikh{/link} en échange du pouvoir et d'une vie sans fin, et le don du démon le refaçonna en quelque chose de plus proche d'un démon. Aucune arme commune ne peut le tuer tant qu'il reste dans les {link:blasted-lands}Terres foudroyées{/link}. Trois soldats du régiment perdu de la {link:horde}Horde{/link} lui furent donnés comme esclaves.]=],
		},
	},
	chapters = {
		{
			title = "L'amulette de Grol",
			hint = [=[Abattez le seigneur des Cognepeur avec une lame qui porte le nom du Souilleur.]=],
			text = [=[Grol fut le premier de la triade à apprendre que l'immortalité a un prix. L'arme forgée au nom même du Souilleur brisa sa protection, et son morceau de l'amulette fut pris sur son corps.]=],
		},
	},
})

Translate("frFR", "archmage-allistarj", {
	title = "Archimage Allistarj",
	subtitle = "Archimage des Shadowsworn",
	found = "Dans les Anneaux du serpent",
	hint = [=[Cherchez l'archimage qui règne sur les cultistes des grottes de l'est.]=],
	allegiance = "Shadowsworn · Razelikh le Souilleur",
	aliases = { "Allistarj" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'archimage Allistarj dirige les cultistes des Shadowsworn des {link:serpent-s-coil}Anneaux du serpent{/link}. Il est l'un des trois qui prirent un morceau de l'amulette de {link:razelikh-the-defiler}Razelikh{/link}, et il est lié au Souilleur par elle. Il fut le tortionnaire du régiment perdu de la {link:horde}Horde{/link}. Dans ses grottes, Trebor et son {link:kirith-the-damned}lieutenant Kirith{/link} furent tourmentés tour à tour, chacun forcé de regarder l'autre, et ce sont les expériences d'Allistarj qui brisèrent l'âme de Kirith. Trois des soldats du régiment le servent encore.]=],
		},
	},
	chapters = {
		{
			title = "L'amulette d'Allistarj",
			hint = [=[Affrontez l'archimage dans les Anneaux du serpent avec le fléau du Souilleur.]=],
			text = [=[L'archimage avait vendu son âme contre le pouvoir de tourmenter autrui. Quand il tomba, son tiers de l'amulette lui fut pris.]=],
		},
	},
})

Translate("frFR", "lady-sevine", {
	title = "Dame Sevine",
	subtitle = "Démoniste des Shadowsworn",
	found = [=[L'Autel des tempêtes, à la lisière ouest des Terres foudroyées]=],
	hint = [=[Cherchez la démoniste qui entretient un autel dans les collines de l'ouest.]=],
	allegiance = "Shadowsworn · Razelikh le Souilleur",
	aliases = { "Sevine" },
	sections = {
		{
			title = "Résumé",
			text = [=[Dame Sevine est une démoniste des Shadowsworn et l'une des trois capitaines liés à {link:razelikh-the-defiler}Razelikh le Souilleur{/link}. Elle tient l'Autel des tempêtes, à la lisière ouest des terres désolées, où ses cultistes pratiquent leurs rites parmi les exécuteurs et les tisseurs d'effroi de la secte. Comme ses compagnons, elle porte un tiers de l'amulette du Souilleur, et comme eux, elle ne peut être tuée sur ces terres par des moyens ordinaires. Trois soldats du régiment perdu de la {link:horde}Horde{/link} sont liés à son service.]=],
		},
	},
	chapters = {
		{
			title = "L'amulette de Sevine",
			hint = "Montez à l'Autel des tempêtes avec le fléau du Souilleur.",
			text = [=[Sevine avait dressé son autel pour invoquer les orages des terres désolées. Il ne la sauva pas. Son morceau de l'amulette fut le dernier des trois.]=],
		},
	},
})

Translate("frFR", "kirith-the-damned", {
	title = "Kirith le Damné",
	subtitle = "Le lieutenant brisé",
	found = "La grotte la plus profonde des Anneaux du serpent",
	hint = [=[Découvrez ce qu'il advint du lieutenant qui ne sortit jamais des grottes.]=],
	allegiance = "Horde (jadis)",
	aliases = { "Kirith", "lieutenant Kirith" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kirith était le lieutenant de Trebor, le commandant d'un régiment de la {link:horde}Horde{/link} perdu dans les {link:blasted-lands}Terres foudroyées{/link}. Lui et son commandant furent torturés côte à côte par l'archimage {link:archmage-allistarj}Allistarj{/link}. Lors d'un répit dans leur tourment, c'est Kirith qui apprit comment les soldats liés du régiment pourraient être libérés. Sa propre volonté finit par céder. Les expériences tordirent son âme jusqu'à en faire une bête gangrenée qui hante le fond des {link:serpent-s-coil}Anneaux du serpent{/link}.]=],
		},
	},
	chapters = {
		{
			title = "L'esprit de Kirith",
			hint = "Libérez le lieutenant de la bête qu'il est devenu.",
			text = [=[Quand la bête fut tuée, l'esprit de Kirith s'en éleva. Il avait peu de temps et il ne le gaspilla pas. Il parla de la triade et de l'amulette que partageaient les trois capitaines, la seule clé capable d'invoquer {link:razelikh-the-defiler}le Souilleur{/link}. Puis il renvoya ses sauveteurs auprès de son commandant.]=],
		},
	},
})

Translate("frFR", "deathly-usher", {
	title = "Deathly Usher",
	subtitle = "Gardien de l'escalier du Souilleur",
	found = "Au pied de la Cime du Souilleur",
	hint = [=[Parlez au spectre qui attend au pied de la montagne du Souilleur.]=],
	sections = {
		{
			title = "Résumé",
			text = [=[Le Deathly Usher est un spectre qui attend au pied de la {link:rise-of-the-defiler}Cime du Souilleur{/link}. Il dit être lié à ce monde pour toujours, et il demande ce que les vivants lui veulent. À ceux qui portent l'amulette du Souilleur, il ouvre le chemin du sommet, où {link:razelikh-the-defiler}Razelikh{/link} a son antre. Ce que l'Usher fut de son vivant, et qui l'a lié ici, il ne le dit pas.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune chronique ne nomme l'Usher ni ne dit comment il en vint à servir la montagne.]=],
		},
	},
	mentions = {
		{
			text = [=[Vous êtes {link:razelikh-the-defiler}Rakh'likh{/link}, démon, la route vers l'antre]=],
		},
	},
})

Translate("frFR", "quartermaster-lungertz", {
	title = "Intendant Lungertz",
	subtitle = "Intendant de Rempart-du-Néant",
	found = "Rempart-du-Néant",
	hint = [=[Parlez à l'homme qui compte chaque caisse qui parvient à Rempart-du-Néant.]=],
	allegiance = "Rempart-du-Néant · Kirin Tor",
	aliases = { "Lungertz" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'intendant Lungertz tient les réserves de {link:nethergarde-keep}Rempart-du-Néant{/link}. Il est le lien vital de la forteresse avec les royaumes. Vivres, armes, pierres de puissance et composants dont ses mages ont besoin doivent tous venir par la longue route de {link:stormwind-city}Stormwind{/link}, et il en répond. Beaucoup trop n'arrivent jamais. Les ogres attaquent les caravanes dans le marais, et des chariots se perdent entre {link:darkshire}Darkshire{/link} et la forteresse. Il accueille chaque livraison comme un petit miracle, et parfois c'en est un.]=],
		},
	},
	chapters = {
		{
			title = "La route de Rempart-du-Néant",
			hint = "Portez des fournitures sur la longue route de la forteresse.",
			text = [=[Des pierres de puissance de {link:darkshire}Darkshire{/link} qui auraient perdu leur charge si elles avaient attendu la caravane suivante. Un tonneau marqué à son nom, retrouvé loin de la route. Une dernière caisse sauvée de la caravane détruite du guetteur {link:watcher-biggs}Biggs{/link}, que la forteresse avait tenue pour perdue avec son conducteur. Chacune lui parvint par la main d'un voyageur, et chacune racontait la même histoire. {link:nethergarde-keep}Rempart-du-Néant{/link} manque de tout, et avant tout des cristaux d'Azoran dont ses mages ne peuvent se passer.]=],
		},
	},
	mentions = {
		{
			text = [=[Des fournitures pour {link:nethergarde-keep}Rempart-du-Néant{/link}]=],
		},
		{ text = "Les fournitures perdues" },
		{ text = "Livrer la cargaison" },
	},
})

Translate("frFR", "watcher-mahar-ba", {
	title = "Guetteur Mahar Ba",
	subtitle = "Érudit de Rempart-du-Néant",
	found = "Rempart-du-Néant",
	hint = "Parlez au guetteur qui étudie les écrits de Khadgar.",
	allegiance = "Rempart-du-Néant · Kirin Tor",
	aliases = { "Mahar Ba" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le guetteur Mahar Ba est l'un des érudits de {link:nethergarde-keep}Rempart-du-Néant{/link}. Son travail est l'étude de la {link:dark-portal}Porte des Ténèbres{/link} et des forces qui l'ont créée, et il espère depuis longtemps lire les pensées du fondateur de la forteresse à ce sujet. Il a fait venir de {link:stormwind-city}Stormwind{/link} une copie des essais de {link:khadgar}Khadgar{/link} sur la rencontre des mondes, et il les a attendus longtemps.]=],
		},
	},
	chapters = {
		{
			title = "La requête de Mazen",
			hint = "Retrouvez l'essai perdu sur la route à travers le marais.",
			text = [=[L'essai fut envoyé par maître Mazen, de l'académie des arcanes de {link:stormwind-city}Stormwind{/link}, aux mains d'une jeune acolyte. Elle le perdit dans {link:swamp-of-sorrows}le Marais des Chagrins{/link} en fuyant les plantes marcheuses du marais. Quand il parvint enfin à {link:nethergarde-keep}Rempart-du-Néant{/link}, Mahar Ba avait hâte de commencer. Entrevoir l'esprit de {link:khadgar}Khadgar{/link}, dit-il, était une joie sans mesure.]=],
		},
	},
	mentions = {
		{ text = "La requête de Mazen" },
	},
})

Translate("frFR", "thadius-grimshade", {
	title = "Thadius Grimshade",
	subtitle = "Devin de Rempart-du-Néant",
	found = "La tour des mages de Rempart-du-Néant",
	hint = [=[Cherchez le devin Wildhammer dans la tour de Rempart-du-Néant.]=],
	allegiance = "Clan Wildhammer",
	aliases = { "Grimshade" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thadius Grimshade est un {link:dwarves}nain{/link} Wildhammer et un devin. Il quitta le {link:aerie-peak}Nid-de-l'Aigle{/link} il y a des années en quête d'un savoir plus sombre, et il lui a trouvé une place dans la tour des mages de {link:nethergarde-keep}Rempart-du-Néant{/link}. Son ancien clan ne l'a pas oublié, et lui ne l'a pas oublié non plus. Il met encore ses arts au service des Wildhammer, mais jamais pour rien.]=],
		},
	},
	chapters = {
		{
			title = "La divination",
			hint = "Apportez au devin une plume de griffon, et payez son prix.",
			text = [=[Les maîtres des griffons du {link:aerie-peak}Nid-de-l'Aigle{/link} lui envoyèrent une plume du nid de Sharpbeak, un jeune griffon qui avait été volé. Grimshade demanda d'abord un prix : le médaillon du troll Nekrum Gutchewer de {red:zul-farrak}Zul'Farrak{/red}, qui avait accordé à son propriétaire une vie anormalement longue. Il espérait en apprendre le secret sans sa malédiction. Quand le médaillon fut à lui, il accomplit sa divination, suivit le fil de la plume jusqu'au griffon, et trouva Sharpbeak retenu prisonnier dans une cité troll des {link:the-hinterlands}Hinterlands{/link}.]=],
		},
	},
	mentions = {
		{ text = "Le médaillon de Nekrum" },
		{ text = "Retour dans les {link:the-hinterlands}Hinterlands{/link}" },
	},
})

Translate("frFR", "ambassador-ardalan", {
	title = "Ambassadeur Ardalan",
	subtitle = "Envoyé à Rempart-du-Néant",
	hint = "Parlez à l'envoyé qui plaide pour une alliance improbable.",
	aliases = { "Ardalan" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'ambassadeur Ardalan est un envoyé elfe à {link:nethergarde-keep}Rempart-du-Néant{/link}. Il défend une opinion que peu de soldats de la forteresse veulent entendre. L'{link:alliance}Alliance{/link}, dit-il, gaspille ses forces à combattre les orcs pour une terre brûlée, tandis que la vraie puissance des {link:blasted-lands}Terres foudroyées{/link} croît en force et en nombre. Si les royaumes ne mettent pas leur querelle de côté, la {link:burning-legion}Légion ardente{/link} les mettra un jour tous deux en déroute.]=],
		},
	},
	chapters = {
		{
			title = "Querelles mesquines",
			hint = "Portez le conseil de l'ambassadeur au fantôme de la Horde.",
			text = [=[Ardalan envoya ceux qui voulaient bien l'écouter à la frontière du marais, auprès du fantôme d'un commandant de la {link:horde}Horde{/link} qui connaissait la vérité des terres désolées. Le fantôme n'avait pas pensé voir le jour où l'{link:alliance}Alliance{/link} combattrait aux côtés de la Horde contre un ennemi commun. Il y consentit.]=],
		},
	},
})

Translate("frFR", "enohar-thunderbrew", {
	title = "Enohar Thunderbrew",
	subtitle = "Brasseuse de Rempart-du-Néant",
	found = "Rempart-du-Néant",
	hint = "Parlez à la naine qui fournit Rempart-du-Néant en bière.",
	allegiance = "Royaume d'Ironforge",
	aliases = { "Enohar" },
	sections = {
		{
			title = "Résumé",
			text = [=[Enohar Thunderbrew est une naine de la famille Thunderbrew qui fournit la garnison de {link:nethergarde-keep}Rempart-du-Néant{/link} en bière. La vie dans la forteresse est rigide et dévouée au devoir, et elle croit qu'un soldat a parfois besoin d'un verre pour alléger le poids de la veille. Les nouvelles du pays lui parviennent encore à travers les terres désolées.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune chronique ne dit quel lien de parenté unit Enohar à {link:ragnar-thunderbrew}Ragnar{/link}, ni comment elle vint à {link:nethergarde-keep}Rempart-du-Néant{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Un vol à Kharanos",
			hint = "Écoutez les nouvelles de Dun Morogh.",
			text = [=[Enohar avait entendu dire que {link:ragnar-thunderbrew}Ragnar Thunderbrew{/link} de {link:kharanos}Kharanos{/link} était furieux. Quelqu'un avait volé l'une des recettes de la famille, et il offrait une bonne somme à qui la lui rapporterait. Elle envoya les volontaires vers le nord.]=],
		},
	},
})

Translate("frFR", "kum-isha-the-collector", {
	title = "Kum'isha le Collectionneur",
	subtitle = "Chercheur de draenéthyste",
	found = "Dans les terres désolées près de la Cime du Souilleur",
	hint = [=[Cherchez l'exilé qui rassemble des cristaux au cœur des terres désolées.]=],
	allegiance = "Les draeneï perdus",
	aliases = { "Kum'isha" },
	sections = {
		{
			title = "Résumé",
			text = [=[Kum'isha le Collectionneur est l'un des draeneï perdus qui errent dans les {link:blasted-lands}Terres foudroyées{/link}, un exilé d'un peuple ancien venu d'un monde au-delà de la {link:dark-portal}Porte des Ténèbres{/link}. Il tient un camp au cœur des terres désolées et rassemble de la draenéthyste, un cristal de sa patrie que l'on trouve encore dans la terre rouge. Il croit qu'avec assez de ce cristal, il pourra ouvrir une faille et ramener son peuple chez lui.]=],
		},
		{
			title = "Importance",
			text = [=[Kum'isha est amer, fier et prompt à la répartie. {link:humans}Humains{/link} et orcs se plaignent chacun de la puanteur de l'autre, observe-t-il, mais pour son nez, tous les peuples de ce monde sentent la même chose, et ce qu'il sent sur eux, c'est la cupidité. La cupidité lui a coûté sa patrie, dit-il, et la cupidité paiera son retour. Il cède volontiers ses trésors à ceux qui lui apportent des cristaux, et il les méprise d'accepter l'échange.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il fouille les {link:blasted-lands}Terres foudroyées{/link} en quête de draenéthyste, surtout des rares sphères sans défaut.
• Il a tenté d'ouvrir une faille vers sa patrie.
• Il paie chaque fragment de cristal qu'on lui apporte, et il méprise ceux qui les apportent.]=],
		},
		{
			title = "Ce que l'on ignore",
			text = [=[Aucune chronique ne dit comment Kum'isha et ses compagnons vinrent dans les {link:blasted-lands}Terres foudroyées{/link}, ni depuis combien de temps ils y errent.]=],
		},
	},
	chapters = {
		{
			title = "La sphère sans défaut",
			hint = [=[Apportez au collectionneur le cristal le plus rare des terres désolées.]=],
			text = [=[Des draeneï ont passé des vies entières à chercher une seule sphère de draenéthyste sans défaut, dit Kum'isha, et sont morts sans avoir achevé leur quête. Quand on en plaça une entre ses mains, il ne put y croire. Il tenta aussitôt de faire apparaître un portail vers sa patrie. La tentative échoua. Il ne perdit pas espoir. Il demanda une autre sphère.]=],
		},
		{
			title = "Le rebut d'un draeneï",
			hint = [=[Apportez au collectionneur les fragments moindres du cristal.]=],
			text = [=[Les fragments imparfaits de draenéthyste n'ouvriront jamais de chemin vers la patrie. Pourtant Kum'isha les prend, car ils peuvent servir son peuple d'autres manières, et il les paie avec les trésors de ce monde, qu'il appelle du rebut. Il répète les mêmes paroles méprisantes à chaque vendeur bien des fois par jour. Il avoue qu'il abhorre ce monde.]=],
		},
	},
	mentions = {
		{ text = "Servir Kum'isha" },
		{ text = "Les entreprises de Kum'isha" },
		{ text = "Tout compte en grande quantité" },
		{ text = "Le rebut d'un draeneï..." },
	},
})

Translate("frFR", "bloodmage-drazial", {
	title = "Mage de sang Drazial",
	subtitle = "Étudiant de la force des bêtes",
	found = [=[Juste à l'intérieur de la frontière nord des Terres foudroyées]=],
	hint = [=[Parlez au mage de sang elfe qui étudie les bêtes des terres désolées.]=],
	aliases = { "Drazial" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le mage de sang Drazial est un elfe de sang qui étudie les bêtes des {link:blasted-lands}Terres foudroyées{/link} avec sa sœur {link:bloodmage-lynnore}Lynnore{/link}. Il croit que l'énergie libérée à l'ouverture de la {link:dark-portal}Porte des Ténèbres{/link} s'est infiltrée dans les créatures des terres désolées et les a forcées à changer. Il étudie leurs corps. Les mâchoires des hyènes Snickerfang, l'endurance des sangliers et la vitesse des scorpides finissent toutes dans ses analyses, dont il tire des élixirs d'une grande force. Il prévient qu'ils ne sont pas sans prix.]=],
		},
	},
	mentions = {
		{ text = "Bajoues de Snickerfang" },
		{ text = "La vitalité du sanglier" },
		{ text = "Le frappeur décisif" },
	},
	bonds = {
		{ id = "bloodmage-lynnore", name = "Mage de sang Lynnore", note = "sa sœur et collègue érudite" },
	},
})

Translate("frFR", "bloodmage-lynnore", {
	title = "Mage de sang Lynnore",
	subtitle = "Étudiante de l'esprit des bêtes",
	found = [=[Juste à l'intérieur de la frontière nord des Terres foudroyées]=],
